 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); bg=grid[0][0]
    # The source is the compact non-background multicolor component. Its
    # occupied cells define a stamp; every isolated marker receives it centered.
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                y,x=q.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    z=(y+dy,x+dx)
                    if 0<=z[0]<h and 0<=z[1]<w and grid[z[0]][z[1]]!=bg and z not in seen:
                        seen.add(z); q.append(z)
            comps.append(comp)
    src=max(comps,key=len)
    r0=min(r for r,c in src); r1=max(r for r,c in src)
    c0=min(c for r,c in src); c1=max(c for r,c in src)
    stamp=[(r-r0,c-c0,grid[r][c]) for r,c in src]
    srcset=set(src)
    # Markers have the same color as the source's leading color, and are
    # isolated. In this task that is color 3; infer as most frequent other color.
    counts={}
    for comp in comps:
        if comp is src: continue
        for r,c in comp: counts[grid[r][c]]=counts.get(grid[r][c],0)+1
    marker=max(counts,key=counts.get)
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=marker or (r,c) in srcset: continue
            for dy,dx,v in stamp:
                y=r+dy-(r1-r0)//2; x=c+dx-(c1-c0)//2
                if 0<=y<h and 0<=x<w: out[y][x]=v
    return out

if __name__ == '__main__':
    print('ready')
